//! SQLite catalog and bounded streaming storage.
mod storage;
pub use storage::{Error, Store};

use depot_domain::{identifier, Artifact, Page, Repository};
use futures_util::{Stream, StreamExt};
use rusqlite::{params, Connection, OptionalExtension};
use sha2::{Digest, Sha256};
use std::{path::{Path, PathBuf}, sync::{atomic::{AtomicU64, Ordering}, Mutex}, time::{SystemTime, UNIX_EPOCH}};
use tokio::io::AsyncWriteExt;
static NEXT: AtomicU64 = AtomicU64::new(0);
#[derive(Debug)]
pub enum Error { Invalid, Missing, Conflict, Storage }
impl std::fmt::Display for Error {
 fn fmt(&self,f:&mut std::fmt::Formatter<'_>)->std::fmt::Result { write!(f,"{:?}",self) }
}
impl std::error::Error for Error {}
impl From<rusqlite::Error> for Error { fn from(_:rusqlite::Error)->Self { Self::Storage } }
impl From<std::io::Error> for Error { fn from(_:std::io::Error)->Self { Self::Storage } }
impl From<depot_domain::Invalid> for Error { fn from(_:depot_domain::Invalid)->Self { Self::Invalid } }
fn now()->u64 { SystemTime::now().duration_since(UNIX_EPOCH).unwrap_or_default().as_secs() }
pub struct Store { root: PathBuf, db: Mutex<Connection> }
impl Store {
 pub fn open(root:impl AsRef<Path>)->Result<Self,Error> {
  let root=root.as_ref().to_path_buf();
  std::fs::create_dir_all(root.join("tmp"))?;
  std::fs::create_dir_all(root.join("objects"))?;
  let db=Connection::open(root.join("catalog.sqlite"))?;
  db.execute_batch("PRAGMA journal_mode=WAL; PRAGMA synchronous=OFF; PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS repos(name TEXT PRIMARY KEY,description TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS artifacts(repo TEXT NOT NULL,name TEXT NOT NULL,version TEXT NOT NULL,size INTEGER NOT NULL DEFAULT 0,sha TEXT NOT NULL DEFAULT '',content_type TEXT NOT NULL,created INTEGER NOT NULL,state TEXT NOT NULL,token TEXT NOT NULL,PRIMARY KEY(repo,name,version),FOREIGN KEY(repo) REFERENCES repos(name));")?;
  let store=Self{root,db:Mutex::new(db)};
  store.reconcile()?;
  Ok(store)
 }
 fn reconcile(&self)->Result<(),Error> {
  let db=self.db.lock().map_err(|_|Error::Storage)?;
  let pending:Vec<(String,String,String)>=db.prepare("SELECT repo,name,version FROM artifacts WHERE state!='ready'")?.query_map([],|r|Ok((r.get(0)?,r.get(1)?,r.get(2)?)))?.collect::<Result<_,_>>()?;
  for (r,n,v) in pending { let path=self.object(&r,&n,&v); if path.exists(){std::fs::remove_file(path)?;} }
  db.execute("DELETE FROM artifacts WHERE state!='ready'",[])?;
  for item in std::fs::read_dir(self.root.join("tmp"))? { let p=item?.path(); if p.is_file(){std::fs::remove_file(p)?;} }
  Ok(())
 }
 fn object(&self,r:&str,n:&str,v:&str)->PathBuf { self.root.join("objects").join(r).join(n).join(v) }
 pub fn create_repo(&self,name:&str,description:&str)->Result<Repository,Error> {
  identifier(name)?;
  let db=self.db.lock().map_err(|_|Error::Storage)?;
  if db.query_row("SELECT 1 FROM repos WHERE name=?",[name],|_|Ok(())).optional()?.is_some(){return Err(Error::Conflict);}
  let repo=Repository{name:name.into(),description:description.into(),created:now()};
  db.execute("INSERT INTO repos VALUES(?,?,?)",params![name,description,repo.created])?;
  Ok(repo)
 }
 pub fn repo(&self,name:&str)->Result<Repository,Error> {
  identifier(name)?;
  let db=self.db.lock().map_err(|_|Error::Storage)?;
  db.query_row("SELECT name,description,created FROM repos WHERE name=?",[name],|r|Ok(Repository{name:r.get(0)?,description:r.get(1)?,created:r.get(2)?})).optional()?.ok_or(Error::Missing)
 }
 pub fn repos(&self,page:u64,size:u64)->Result<Page<Repository>,Error> {
  let db=self.db.lock().map_err(|_|Error::Storage)?;
  let total=db.query_row("SELECT count(*) FROM repos",[],|r|r.get(0))?;
  let items=db.prepare("SELECT name,description,created FROM repos ORDER BY name LIMIT ? OFFSET ?")?.query_map(params![size,(page-1)*size],|r|Ok(Repository{name:r.get(0)?,description:r.get(1)?,created:r.get(2)?}))?.collect::<Result<_,_>>()?;
  Ok(Page{items,page,page_size:size,total})
 }
 pub fn artifact(&self,repo:&str,name:&str,version:&str)->Result<Artifact,Error> {
  identifier(repo)?; identifier(name)?; identifier(version)?;
  let db=self.db.lock().map_err(|_|Error::Storage)?;
  db.query_row("SELECT repo,name,version,size,sha,content_type,created FROM artifacts WHERE repo=? AND name=? AND version=? AND state='ready'",params![repo,name,version],record).optional()?.ok_or(Error::Missing)
 }
 pub fn artifacts(&self,repo:&str,prefix:&str,page:u64,size:u64)->Result<Page<Artifact>,Error> {
  self.repo(repo)?;
  let db=self.db.lock().map_err(|_|Error::Storage)?;
  let total=db.query_row("SELECT count(*) FROM artifacts WHERE repo=? AND state='ready' AND substr(name,1,length(?))=?",params![repo,prefix,prefix],|r|r.get(0))?;
  let items=db.prepare("SELECT repo,name,version,size,sha,content_type,created FROM artifacts WHERE repo=? AND state='ready' AND substr(name,1,length(?))=? ORDER BY name,version LIMIT ? OFFSET ?")?.query_map(params![repo,prefix,prefix,size,(page-1)*size],record)?.collect::<Result<_,_>>()?;
  Ok(Page{items,page,page_size:size,total})
 }
 pub async fn upload<S>(&self,repo:&str,name:&str,version:&str,content_type:&str,stream:S)->Result<Artifact,Error>
 where S:Stream<Item=Result<Vec<u8>,String>>+Send {
  identifier(repo)?; identifier(name)?; identifier(version)?; self.repo(repo)?;
  let token=format!("{}-{}-{}",std::process::id(),now(),NEXT.fetch_add(1,Ordering::Relaxed));
  {
   let db=self.db.lock().map_err(|_|Error::Storage)?;
   if db.query_row("SELECT 1 FROM artifacts WHERE repo=? AND name=? AND version=?",params![repo,name,version],|_|Ok(())).optional()?.is_some(){return Err(Error::Conflict);}
   db.execute("INSERT INTO artifacts(repo,name,version,content_type,created,state,token) VALUES(?,?,?,?,?,'uploading',?)",params![repo,name,version,content_type,now(),token])?;
  }
  let temp=self.root.join("tmp").join(&token);
  let result=self.stream_to(&temp,stream).await;
  let (size,sha)=match result { Ok(r)=>r,Err(e)=>{let _=tokio::fs::remove_file(&temp).await;self.abort(repo,name,version,&token)?;return Err(e);} };
  let destination=self.object(repo,name,version);
  tokio::fs::create_dir_all(destination.parent().ok_or(Error::Storage)?).await?;
  tokio::fs::rename(&temp,&destination).await?;
  if std::env::var("DEPOT_FAULT").as_deref()==Ok("after_rename") && version=="fault" { std::process::exit(86); }
  {
   let db=self.db.lock().map_err(|_|Error::Storage)?;
   db.execute("UPDATE artifacts SET size=?,sha=?,state='ready' WHERE repo=? AND name=? AND version=? AND token=?",params![size,sha,repo,name,version,token])?;
  }
  self.artifact(repo,name,version)
 }
 async fn stream_to<S>(&self,path:&Path,stream:S)->Result<(u64,String),Error>
 where S:Stream<Item=Result<Vec<u8>,String>>+Send {
  let mut file=tokio::fs::OpenOptions::new().write(true).create_new(true).open(path).await?;
  let mut hash=Sha256::new(); let mut size=0u64;
  futures_util::pin_mut!(stream);
  while let Some(chunk)=stream.next().await { let chunk=chunk.map_err(|_|Error::Storage)?; size=size.checked_add(chunk.len() as u64).ok_or(Error::Storage)?;hash.update(&chunk);file.write_all(&chunk).await?; }
  file.flush().await?; drop(file);
  Ok((size,format!("{:x}",hash.finalize())))
 }
 fn abort(&self,r:&str,n:&str,v:&str,token:&str)->Result<(),Error> { self.db.lock().map_err(|_|Error::Storage)?.execute("DELETE FROM artifacts WHERE repo=? AND name=? AND version=? AND token=? AND state='uploading'",params![r,n,v,token])?; Ok(()) }
 pub async fn download(&self,r:&str,n:&str,v:&str)->Result<(Artifact,tokio::fs::File),Error> {
  let meta=self.artifact(r,n,v)?;
  let file=tokio::fs::File::open(self.object(r,n,v)).await.map_err(|e|if e.kind()==std::io::ErrorKind::NotFound{Error::Missing}else{Error::Storage})?;
  Ok((meta,file))
 }
 pub async fn delete(&self,r:&str,n:&str,v:&str)->Result<(),Error> {
  identifier(r)?;identifier(n)?;identifier(v)?;
  {
   let db=self.db.lock().map_err(|_|Error::Storage)?;
   if db.execute("UPDATE artifacts SET state='deleting' WHERE repo=? AND name=? AND version=? AND state='ready'",params![r,n,v])?==0{return Err(Error::Missing);}
  }
  if std::env::var("DEPOT_FAULT").as_deref()==Ok("delete_mark") && v=="fault-delete" {std::process::exit(87);}
  match tokio::fs::remove_file(self.object(r,n,v)).await {Ok(())=>{},Err(e) if e.kind()==std::io::ErrorKind::NotFound=>{},Err(_)=>return Err(Error::Storage)}
  self.db.lock().map_err(|_|Error::Storage)?.execute("DELETE FROM artifacts WHERE repo=? AND name=? AND version=? AND state='deleting'",params![r,n,v])?;
  Ok(())
 }
}
fn record(row:&rusqlite::Row<'_>)->rusqlite::Result<Artifact> { Ok(Artifact{repository:row.get(0)?,name:row.get(1)?,version:row.get(2)?,size:row.get(3)?,sha256:row.get(4)?,content_type:row.get(5)?,created:row.get(6)?}) }

use depot_store::{Store,Error};
use futures_util::stream;
#[tokio::test]
async fn streamed_publication_and_reopen() {
 let root=std::env::current_dir().unwrap().join(format!("test-data/store-{}",std::process::id()));
 if root.exists(){std::fs::remove_dir_all(&root).unwrap();}
 let s=Store::open(&root).unwrap();s.create_repo("repo","test").unwrap();
 let a=s.upload("repo","artifact","opaque-v1","application/octet-stream",stream::iter(vec![Ok(vec![0,1]),Ok(vec![2,255])])).await.unwrap();
 assert_eq!(a.size,4);assert_eq!(a.sha256.len(),64);
 assert!(matches!(s.upload("repo","artifact","opaque-v1","x",stream::empty()).await,Err(Error::Conflict)));
 let broken=stream::iter(vec![Ok(vec![1,2]),Err("disconnect".to_string())]);
 assert!(s.upload("repo","bad","v1","x",broken).await.is_err());
 assert!(matches!(s.artifact("repo","bad","v1"),Err(Error::Missing)));
 drop(s); let s=Store::open(&root).unwrap();assert_eq!(s.artifact("repo","artifact","opaque-v1").unwrap().sha256,a.sha256);
 s.delete("repo","artifact","opaque-v1").await.unwrap();drop(s);std::fs::remove_dir_all(root).unwrap();
}
